& "$env:ProgramFiles\Inkscape\bin\inkscape.com" ".\default.svg" --export-area-page --export-width=1200 --export-height=630 --export-filename="$env:TEMP\og-base.png"; $best=$null; 256,240,224,208,192,176,160,144,128,112,96,80,64,48,32,24,16 | ForEach-Object { $n=$_; $out=".\og-$n.png"; ffmpeg -loglevel error -y -i "$env:TEMP\og-base.png" -filter_complex "[0:v]split[a][b];[a]palettegen=max_colors=$n[p];[b][p]paletteuse=dither=sierra2_4a" -frames:v 1 -update 1 $out; $s=(Get-Item $out).Length; if($s -le 500KB -and ($null -eq $best -or $s -gt $best.Size)){ if($best){Remove-Item $best.Path -Force}; $best=[PSCustomObject]@{Path=$out;Size=$s} } else { Remove-Item $out -Force } }; Remove-Item "$env:TEMP\og-base.png" -Force; if($best){Move-Item $best.Path ".\default.png" -Force; $f=Get-Item ".\default.png"; Write-Host ("default.png -> {0:N1} KB" -f ($f.Length/1KB))}else{Write-Host "Could not produce a PNG <= 500 KB"}